package edu.pe.cibertec.saibm.usuario.infrastructure.persistence; import java.util.*; import org.springframework.beans.factory.ObjectProvider; import org.springframework.stereotype.Component; import org.springframework.transaction.annotation.Transactional; import com.fasterxml.jackson.databind.ObjectMapper; import com.fasterxml.jackson.databind.json.JsonMapper; import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule; import edu.pe.cibertec.saibm.usuario.application.port.out.*; import edu.pe.cibertec.saibm.usuario.domain.event.UserEvent; import edu.pe.cibertec.saibm.usuario.domain.model.*; @Component @Transactional public class UserPersistenceAdapter implements UserStorePort,UserEventPublisher {private final UserJpaRepository users;private final UserOutboxRepository outbox;private final ObjectMapper mapper;public UserPersistenceAdapter(UserJpaRepository u,UserOutboxRepository o,ObjectProvider<ObjectMapper> m){users=u;outbox=o;mapper=m.getIfAvailable(()->JsonMapper.builder().addModule(new JavaTimeModule()).build());}public Optional<UserProfile> find(UUID id){return users.findById(id).map(UserJpaEntity::domain);}@Transactional(readOnly=true)public List<UserProfile> search(String q){return users.search(q==null?"":q.trim()).stream().map(UserJpaEntity::domain).toList();}public void save(UserProfile p){users.saveAndFlush(new UserJpaEntity(p));}public Optional<UserProfile> byEmail(String e){return users.findByEmailIgnoreCase(e).map(UserJpaEntity::domain);}public void publish(UserEvent e){try{outbox.saveAndFlush(new UserOutboxJpaEntity(e,mapper.writeValueAsString(e)));}catch(Exception x){throw new IllegalStateException("Unable to persist user event",x);}}}
